      "Вмешайте тёртые помидоры, рубленый чеснок и соль. Томите без крышки 18–22 минуты, пока почти вся свободная жидкость не испарится, а овощи не станут мягкими.",
      "В отдельной сковороде на оставшемся масле поджарьте яйцо до желаемой плотности желтка и полностью схватившегося белка. Положите на горячие овощи и подайте с хлебом.",
