      "Пока варится лапша, положите тонкие кусочки бекона на холодную сковороду. Постепенно нагревайте 5–7 минут, пока жир не вытопится и края не захрустят. Бекон переложите на тарелку.",
      "В горячем жире перемешайте откинутую лапшу. Снимите с плиты, добавьте половину рассыпчатого творога и сметаны. Слегка разбавьте водой от варки. Сверху подайте оставшийся творог, сметану и бекон.",
