    steps: [
      "Для домашнего варианта возьмите крупную пшеничную крупу. Промойте и отварите с солью в 165 мл воды на слабом огне 20–30 минут до мягкости. Избыток воды откиньте.",
      "Отдельно залейте мак кипятком на 15 минут и промойте изюм. Слейте воду с мака и разотрите семена в ступке, пока масса не посветлеет. Порубите орехи.",
      "Растворите мёд в двух ложках тёплой воды, добавьте мак, изюм и орехи. Перемешайте с чуть тёплой кашей и дайте ей пропитаться 10 минут.",
    ],
